const player=document.getElementById('film-player');if(player){const id=new URLSearchParams(location.search).get('film');if(films[id]){document.getElementById('film-title').textContent=films[id];document.title=films[id]+' — Miguel Nascimento';const iframe=document.createElement('iframe');iframe.src='https://drive.google.com/file/d/'+id+'/preview';iframe.title=films[id];iframe.allow='autoplay; fullscreen; picture-in-picture';iframe.allowFullscreen=true;player.append(iframe);const link=document.createElement('a');link.href='https://drive.google.com/file/d/'+id+'/view';link.target='_blank';link.rel='noopener';link.textContent='Open in Google Drive ↗';document.getElementById('film-note').append('If the player requests access, ',link);}else{player.classList.remove('video-shell');player.textContent='Choose a project from the production page to watch.'}}
const form=document.getElementById('inquiry');if(form){const status=document.getElementById('form-status');function draft(){const d=new FormData(form);return [...d.entries()].map(([k,v])=>k.charAt(0).toUpperCase()+k.slice(1)+': '+v).join('\n\n')}form.addEventListener('submit',e=>{e.preventDefault();for(const field of form.querySelectorAll('[required]')){field.value=field.value.trim();}if(!form.reportValidity())return;const text=draft();document.getElementById('draft-copy').value=text;document.getElementById('email-fallback').hidden=false;const subject='Portfolio inquiry — '+form.elements.project.value;document.getElementById('open-email').href='mailto:Migueln1510@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(text);document.getElementById('open-gmail').href='https://mail.google.com/mail/?view=cm&fs=1&to=Migueln1510%40gmail.com&su='+encodeURIComponent(subject)+'&body='+encodeURIComponent(text);status.textContent='Your inquiry is ready. Choose an email option below, then send it there. Nothing has been sent yet.';document.getElementById('draft-copy').focus()});document.getElementById('copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft());status.textContent='Inquiry copied.'}catch{document.getElementById('draft-copy').select();status.textContent='Select and copy the prepared inquiry below.'}});if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'stage_portfolio_inquiry',description:'Fill the visible inquiry form for review. Does not send an email or open an email app.',inputSchema:{type:'object',properties:Object.fromEntries(['name','email','phone','project','timeline','budget','message'].map(k=>[k,{type:'string',maxLength:k==='message'?3000:200}])),required:['name','email','project','message'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object')throw new Error('Inquiry fields are required.');for(const k of ['name','email','project','message'])if(typeof input[k]!=='string'||!input[k].trim())throw new Error(k+' is required.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.email))throw new Error('Enter a valid email.');for(const [k,v]of Object.entries(input)){if(!['name','email','phone','project','timeline','budget','message'].includes(k)||typeof v!=='string'||v.length>(k==='message'?3000:200))throw new Error('Invalid field: '+k)}for(const [k,v]of Object.entries(input))form.elements[k].value=v;status.textContent='Inquiry ready for your review. Nothing has been sent.';return{status:'staged',sent:false}}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}}

// Keep navigation useful when a film link is missing or outdated.
if(player){const active=new URLSearchParams(location.search).get('film'),isActing=actingIds.includes(active)||location.pathname.startsWith('/acting/'),allKeys=Object.keys(films).filter(id=>actingIds.includes(id)===isActing),position=allKeys.indexOf(active),keys=position<0?allKeys.slice(0,4):allKeys.slice(Math.max(0,position-1),position+3);const list=document.createElement('nav');list.className='film-navigation';list.setAttribute('aria-label','More selected films');for(const id of keys){const a=document.createElement('a');a.href=(isActing?'/acting/watch/':'/production/watch/')+'?film='+id;a.textContent=films[id];if(id===active)a.setAttribute('aria-current','page');list.append(a)}player.parentElement.append(list);if(!films[active]){document.getElementById('film-title').textContent='Choose a film';}const note=document.getElementById('film-note');if(films[active]){const retry=document.createElement('button');retry.type='button';retry.className='text-button';retry.textContent='Reload player';retry.addEventListener('click',()=>{const f=player.querySelector('iframe');f.src='https://drive.google.com/file/d/'+active+'/preview'});note.append(' ',retry);}}

const search=document.getElementById('video-search'),category=document.getElementById('video-category');if(search&&category){const cards=[...document.querySelectorAll('[data-video]')];function filterVideos(){const q=search.value.trim().toLowerCase();let count=0;for(const card of cards){const show=(!category.value||card.dataset.group===category.value)&&card.textContent.toLowerCase().includes(q);card.hidden=!show;if(show)count++;}document.getElementById('video-count').textContent=count+' videos';document.getElementById('video-empty').hidden=count!==0;}search.addEventListener('input',filterVideos);category.addEventListener('change',filterVideos);filterVideos();}
